package exercise

import (
	"math"
	"reflect"
	"testing"
	"time"
)

const inf = math.MaxInt

func TestAllPairsDistances(t *testing.T) {
	cases := []struct {
		name  string
		n     int
		edges []Edge
		want  [][]int
	}{
		{
			name:  "four-vertex example",
			n:     4,
			edges: []Edge{{0, 1, -5}, {0, 2, 2}, {0, 3, 3}, {1, 2, 4}, {2, 3, 1}},
			want: [][]int{
				{0, -5, -1, 0},
				{inf, 0, 4, 5},
				{inf, inf, 0, 1},
				{inf, inf, inf, 0},
			},
		},
		{
			name:  "negative edge makes the longer route shorter",
			n:     3,
			edges: []Edge{{0, 1, 4}, {0, 2, 5}, {2, 1, -3}},
			want: [][]int{
				{0, 2, 5},
				{inf, 0, inf},
				{inf, -3, 0},
			},
		},
		{
			name:  "cycle adding up to zero is not negative",
			n:     3,
			edges: []Edge{{0, 1, 1}, {1, 2, 2}, {2, 1, -2}},
			want: [][]int{
				{0, 1, 3},
				{inf, 0, 2},
				{inf, -2, 0},
			},
		},
		{
			name:  "positive cycle through a negative edge",
			n:     2,
			edges: []Edge{{0, 1, 2}, {1, 0, -1}},
			want: [][]int{
				{0, 2},
				{-1, 0},
			},
		},
		{
			name:  "edges only go one way",
			n:     2,
			edges: []Edge{{1, 0, 3}},
			want: [][]int{
				{0, inf},
				{3, 0},
			},
		},
		{
			name:  "parallel edges keep the shortest",
			n:     2,
			edges: []Edge{{0, 1, 9}, {0, 1, -2}, {0, 1, 5}},
			want: [][]int{
				{0, -2},
				{inf, 0},
			},
		},
		{
			name:  "chain of negative edges listed backwards",
			n:     5,
			edges: []Edge{{3, 4, -1}, {2, 3, -1}, {1, 2, -1}, {0, 1, -1}},
			want: [][]int{
				{0, -1, -2, -3, -4},
				{inf, 0, -1, -2, -3},
				{inf, inf, 0, -1, -2},
				{inf, inf, inf, 0, -1},
				{inf, inf, inf, inf, 0},
			},
		},
		{
			name: "no edges",
			n:    3,
			want: [][]int{
				{0, inf, inf},
				{inf, 0, inf},
				{inf, inf, 0},
			},
		},
		{
			name: "single vertex",
			n:    1,
			want: [][]int{{0}},
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got, ok := AllPairs(c.n, c.edges)
			if !ok {
				t.Fatalf("reported a negative cycle, but there is none")
			}
			if !reflect.DeepEqual(got, c.want) {
				t.Errorf("got %v, want %v", got, c.want)
			}
		})
	}
}

func TestAllPairsNegativeCycle(t *testing.T) {
	cases := []struct {
		name  string
		n     int
		edges []Edge
	}{
		{
			name:  "cycle 1-2-3 adds up to -3",
			n:     4,
			edges: []Edge{{0, 1, 4}, {1, 2, -6}, {2, 3, 5}, {3, 1, -2}},
		},
		{
			name:  "cycle that vertex 0 cannot reach still counts",
			n:     4,
			edges: []Edge{{0, 1, 2}, {2, 3, 1}, {3, 2, -3}},
		},
		{
			name:  "negative edge from a vertex to itself",
			n:     2,
			edges: []Edge{{1, 1, -1}},
		},
		{
			name:  "cycle at the end of a long chain listed backwards",
			n:     5,
			edges: []Edge{{4, 3, -2}, {3, 4, 1}, {2, 3, 1}, {1, 2, 1}, {0, 1, 1}},
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got, ok := AllPairs(c.n, c.edges)
			if ok {
				t.Fatalf("got %v, true; want a reported negative cycle (nil, false)", got)
			}
			if got != nil {
				t.Errorf("got distances %v alongside false, want nil", got)
			}
		})
	}
}

func TestAllPairsHandlesLargeSparseGraph(t *testing.T) {
	// Three sections of k vertices each:
	//   - a path P0 -> P1 -> ... of zero-length edges,
	//   - fan vertices A1..Ak, reached from the last P by an edge of length i,
	//   - a chain C0 -> C1 -> ... of zero-length edges, entered from each Ai
	//     by an edge of length -2i.
	// From any P the chain is first reached through A1 at -1, then through
	// A2 at -2, and so on: a search that is not handed non-negative lengths
	// walks the whole chain again for every fan vertex, from every P. Floyd-
	// Warshall is no better. Reweighting once lets every search settle each vertex once.
	const k = 1200
	const n = 3 * k
	p := func(i int) int { return i }
	a := func(i int) int { return k + i - 1 }
	c := func(j int) int { return 2*k + j }

	edges := make([]Edge, 0, 4*k)
	for i := 0; i+1 < k; i++ {
		edges = append(edges, Edge{p(i), p(i + 1), 0})
	}
	for i := 1; i <= k; i++ {
		edges = append(edges, Edge{p(k - 1), a(i), i})
		edges = append(edges, Edge{a(i), c(0), -2 * i})
	}
	for j := 0; j+1 < k; j++ {
		edges = append(edges, Edge{c(j), c(j + 1), 0})
	}

	want := func(u, v int) int {
		switch {
		case u == v:
			return 0
		case u < k && v < k: // P to P
			if v > u {
				return 0
			}
		case u < k && v < 2*k: // P to A
			return v - k + 1
		case u < k: // P to C
			return -k
		case u < 2*k && v >= 2*k: // A to C
			return -2 * (u - k + 1)
		case u >= 2*k && v >= 2*k: // C to C
			if v > u {
				return 0
			}
		}
		return inf
	}

	const budget = 3 * time.Second
	type result struct {
		dist [][]int
		ok   bool
	}
	done := make(chan result, 1)
	go func() {
		dist, ok := AllPairs(n, edges)
		done <- result{dist, ok}
	}()

	var got result
	select {
	case got = <-done:
	case <-time.After(budget):
		t.Fatalf("still running after %v on a graph of %d vertices and %d edges: reweight the edges once so none is negative, then run a heap-based shortest-path search from every vertex", budget, n, len(edges))
	}

	if !got.ok {
		t.Fatalf("reported a negative cycle, but the graph has no cycles at all")
	}
	if len(got.dist) != n {
		t.Fatalf("got %d rows, want %d", len(got.dist), n)
	}
	for u := 0; u < n; u++ {
		if len(got.dist[u]) != n {
			t.Fatalf("row %d: got %d distances, want %d", u, len(got.dist[u]), n)
		}
		for v := 0; v < n; v++ {
			if w := want(u, v); got.dist[u][v] != w {
				t.Fatalf("distance from %d to %d: got %d, want %d", u, v, got.dist[u][v], w)
			}
		}
	}
}

