package exercise

import (
	"container/heap"
	"math"
)

type Edge struct {
	From   int
	To     int
	Weight int
}

type item struct {
	vertex int
	dist   int
}

type minHeap []item

func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i].dist < h[j].dist }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(item)) }
func (h *minHeap) Pop() any {
	old := *h
	last := old[len(old)-1]
	*h = old[:len(old)-1]
	return last
}

func AllPairs(n int, edges []Edge) ([][]int, bool) {
	// Bellman-Ford from a virtual source joined to every vertex by a
	// zero-length edge: starting every h at zero is that first round.
	h := make([]int, n)
	for i := 0; i < n; i++ {
		for _, e := range edges {
			if h[e.From]+e.Weight < h[e.To] {
				h[e.To] = h[e.From] + e.Weight
			}
		}
	}
	for _, e := range edges {
		if h[e.From]+e.Weight < h[e.To] {
			return nil, false
		}
	}

	adj := make([][]Edge, n)
	for _, e := range edges {
		e.Weight += h[e.From] - h[e.To]
		adj[e.From] = append(adj[e.From], e)
	}

	dist := make([][]int, n)
	for src := 0; src < n; src++ {
		d := make([]int, n)
		for i := range d {
			d[i] = math.MaxInt
		}
		d[src] = 0
		pq := &minHeap{{vertex: src, dist: 0}}
		for pq.Len() > 0 {
			cur := heap.Pop(pq).(item)
			if cur.dist > d[cur.vertex] {
				continue
			}
			for _, e := range adj[cur.vertex] {
				if next := cur.dist + e.Weight; next < d[e.To] {
					d[e.To] = next
					heap.Push(pq, item{vertex: e.To, dist: next})
				}
			}
		}
		for v := range d {
			if d[v] != math.MaxInt {
				d[v] += h[v] - h[src]
			}
		}
		dist[src] = d
	}
	return dist, true
}
